def state_abstraction(grid_world):
    grid = grid_world['grid']
    rows = len(grid)
    cols = len(grid[0])

    # Create a map to store the abstraction for each cell
    abstract_map = [[-1 for _ in range(cols)] for _ in range(rows)]

    # Iterate over all cells in the grid
    for r in range(rows):
        for c in range(cols):
            # Check if this is a blocked cell or not
            if grid[r][c] == 'X':
                continue

            # Calculate the Manhattan distance to the goal (bottom right corner)
            manhattan_distance = abs(r - (rows - 1)) + abs(c - (cols - 1))

            # Abstract cells based on their Manhattan distance to the goal
            abstract_map[r][c] = manhattan_distance // 3

    # Group the abstracted states by value
    abstraction_groups = {}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 'X':
                group_value = abstract_map[r][c]
                if group_value not in abstraction_groups:
                    abstraction_groups[group_value] = []
                abstraction_groups[group_value].append(grid[r][c])

    # Convert the dictionary of groups to a list of lists
    result = [list(group) for group in abstraction_groups.values()]
    return result

